WITH account AS MATERIALIZED (SELECT id FROM public."user" WHERE discord_id=$1 AND discord_id>0), candidates AS MATERIALIZED (SELECT level.id,level.xx_hash,item.workshop_id,item.file_uid,item.name,item.file_author, COALESCE(points.points,0) AS points,(SELECT count(*) FROM (SELECT * FROM public.record WHERE record_eligible) value WHERE value.id_level=level.id) AS records, (SELECT count(*) FROM (SELECT * FROM public.record WHERE record_eligible) value WHERE value.id_level=level.id AND value.date_created>=clock_timestamp()-interval '30 days') AS popularity,item.created_at,item.updated_at FROM public.level level JOIN LATERAL (SELECT source.* FROM public.level_item source WHERE source.id_level=level.id AND source.deleted=false ORDER BY source.updated_at DESC,source.id DESC LIMIT 1) item ON true LEFT JOIN public.level_points points ON points.id_level=level.id LEFT JOIN (SELECT * FROM public.world_record_global WHERE record_eligible) wr ON wr.id_level=level.id LEFT JOIN account ON true WHERE level.publicly_visible=true AND (NOT $4 OR wr.id_user IS DISTINCT FROM account.id) AND (NOT $5 OR NOT EXISTS(SELECT 1 FROM (SELECT * FROM public.personal_best_global WHERE record_eligible) pb WHERE pb.id_level=level.id AND pb.id_user=account.id)) AND (NOT $6 OR NOT EXISTS(SELECT 1 FROM (SELECT * FROM public.record WHERE record_eligible) value WHERE value.id_level=level.id))) SELECT jsonb_build_object('id',id,'xxHash',xx_hash,'workshopId',workshop_id::text, 'fileUid',file_uid,'name',name,'fileAuthor',file_author,'points',points,'records',records) AS value FROM candidates ORDER BY CASE $2 WHEN 'points' THEN points WHEN 'records' THEN records WHEN 'popularity' THEN popularity ELSE NULL END DESC NULLS LAST, CASE $2 WHEN 'created' THEN created_at WHEN 'updated' THEN updated_at ELSE NULL END DESC NULLS LAST,id ASC LIMIT $3
